using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace SourceGen.Ioc.Test.Helpers;

/// <summary>
/// The rules that each generated file follows (Container.Output.spec, "Requirements for the generated code").
/// Each check returns the problems that it finds, so that tests can check the checks.
/// </summary>
public static partial class GeneratedCodeRules
{
    /// <summary>The lines at the start of each generated file, in this order.</summary>
    public static readonly IReadOnlyList<string> Header =
    [
        "// <auto-generated/>",
        "#nullable enable annotations",
        "#nullable disable warnings",
        "#pragma warning disable SGIOCEXP001",
    ];

    private const string GeneratedCodeName = "global::System.CodeDom.Compiler.GeneratedCode";

    /// <summary>Runs all checks on the generated trees of <paramref name="compilation"/>.</summary>
    public static IReadOnlyList<string> Check(Compilation compilation, IReadOnlyList<SyntaxTree> generatedTrees)
    {
        List<string> problems = [];
        foreach(SyntaxTree tree in generatedTrees)
        {
            string file = Path.GetFileName(tree.FilePath);
            SemanticModel model = compilation.GetSemanticModel(tree);
            problems.AddRange(CheckHeader(tree).Select(p => $"{file}: {p}"));
            problems.AddRange(CheckNoVar(tree).Select(p => $"{file}: {p}"));
            problems.AddRange(CheckNoReflection(tree, model).Select(p => $"{file}: {p}"));
        }

        problems.AddRange(CheckGeneratedCodeAttributes(compilation, generatedTrees));
        return problems;
    }

    public static IEnumerable<string> CheckHeader(SyntaxTree tree)
    {
        string[] lines = tree.GetText().ToString().Split('\n');
        for(int i = 0; i < Header.Count; i++)
        {
            string actual = i < lines.Length ? lines[i].TrimEnd('\r') : "<end of file>";
            if(actual != Header[i])
            {
                yield return $"line {i + 1} is '{actual}', expected '{Header[i]}'";
            }
        }
    }

    public static IEnumerable<string> CheckNoVar(SyntaxTree tree)
    {
        foreach(SyntaxNode node in tree.GetRoot().DescendantNodes())
        {
            if(node is TypeSyntax { IsVar: true } || node.IsKind(SyntaxKind.VarPattern))
            {
                yield return $"'var' at {Line(node)}";
            }
        }
    }

    /// <summary>
    /// Finds each use of reflection: a call, a method group, a constructor, or a type name. A qualifier (the left side of
    /// a member access or a qualified name) is not checked by itself, so that each use is reported one time.
    /// </summary>
    public static IEnumerable<string> CheckNoReflection(SyntaxTree tree, SemanticModel model)
    {
        HashSet<int> reportedLines = [];
        foreach(SyntaxNode node in tree.GetRoot().DescendantNodes())
        {
            bool candidate = node is SimpleNameSyntax or BaseObjectCreationExpressionSyntax;
            bool qualifier = node.Parent is MemberAccessExpressionSyntax access && access.Expression == node
                || node.Parent is QualifiedNameSyntax qualified && qualified.Left == node;
            if(!candidate || qualifier)
            {
                continue;
            }

            SymbolInfo info = model.GetSymbolInfo(node);
            if((info.Symbol ?? info.CandidateSymbols.FirstOrDefault()) is not { } symbol || !IsReflection(symbol))
            {
                continue;
            }

            int line = node.GetLocation().GetLineSpan().StartLinePosition.Line + 1;
            if(reportedLines.Add(line))
            {
                yield return $"reflection '{symbol.ToDisplayString()}' at line {line}";
            }
        }
    }

    private static bool IsReflection(ISymbol symbol)
    {
        INamedTypeSymbol? type = symbol as INamedTypeSymbol ?? symbol.ContainingType;
        if(type is null)
        {
            return false;
        }

        string ns = type.ContainingNamespace?.ToDisplayString() ?? "";
        string typeName = type.OriginalDefinition.ToDisplayString();
        string member = symbol is INamedTypeSymbol ? "" : symbol.Name;
        return ns is "System.Reflection" or "System.Linq.Expressions"
            || ns.StartsWith("System.Reflection.", StringComparison.Ordinal)
            || typeName is "System.Activator" or "Microsoft.Extensions.DependencyInjection.ActivatorUtilities"
            || typeName == "System.Type" && (member.StartsWith("Get", StringComparison.Ordinal) || member is "MakeGenericType" or "MakeArrayType" or "InvokeMember")
            || typeName == "System.Array" && member == "CreateInstance"
            || typeName == "System.Delegate" && member == "CreateDelegate"
            || typeName == "System.Runtime.CompilerServices.RuntimeHelpers" && member == "GetUninitializedObject";
    }

    /// <summary>
    /// A type that the generator declares completely has <c>[GeneratedCode]</c> on exactly one of its declarations. A
    /// partial declaration of a type that the user declares does not have it, and each member and nested type that the
    /// generator declares in it has it.
    /// </summary>
    public static IReadOnlyList<string> CheckGeneratedCodeAttributes(Compilation compilation, IReadOnlyList<SyntaxTree> generatedTrees)
    {
        List<string> problems = [];
        HashSet<SyntaxTree> generated = [.. generatedTrees];
        Dictionary<ISymbol, List<MemberDeclarationSyntax>> generatorTypes = new(SymbolEqualityComparer.Default);

        foreach(SyntaxTree tree in generatedTrees)
        {
            SemanticModel model = compilation.GetSemanticModel(tree);
            foreach(MemberDeclarationSyntax type in tree.GetRoot()
                .DescendantNodes(static n => n is not BaseTypeDeclarationSyntax and not DelegateDeclarationSyntax)
                .OfType<MemberDeclarationSyntax>()
                .Where(static n => n is BaseTypeDeclarationSyntax or DelegateDeclarationSyntax))
            {
                CheckType(type, model);
            }
        }

        foreach((ISymbol symbol, List<MemberDeclarationSyntax> declarations) in generatorTypes)
        {
            int count = declarations.Count(static d => FindAttribute(d.AttributeLists) is not null);
            if(count != 1)
            {
                problems.Add($"type '{symbol.Name}' has [GeneratedCode] on {count} of its {declarations.Count} generated declarations, expected 1");
            }

            foreach(AttributeSyntax attribute in declarations.Select(static d => FindAttribute(d.AttributeLists)).OfType<AttributeSyntax>())
            {
                CheckAttributeForm(attribute, $"type '{symbol.Name}'", problems);
            }
        }

        return problems;

        void CheckType(MemberDeclarationSyntax type, SemanticModel model)
        {
            if(model.GetDeclaredSymbol(type) is not INamedTypeSymbol symbol)
            {
                return;
            }

            bool userDeclared = symbol.DeclaringSyntaxReferences.Any(r => !generated.Contains(r.SyntaxTree));
            if(!userDeclared)
            {
                if(!generatorTypes.TryGetValue(symbol, out List<MemberDeclarationSyntax>? list))
                {
                    generatorTypes[symbol] = list = [];
                }

                list.Add(type);
                return;
            }

            if(FindAttribute(type.AttributeLists) is not null)
            {
                problems.Add($"{File(type)}: the partial declaration of user type '{symbol.Name}' has [GeneratedCode]");
            }

            if(type is not TypeDeclarationSyntax withMembers)
            {
                return;
            }

            foreach(MemberDeclarationSyntax member in withMembers.Members)
            {
                if(member is BaseTypeDeclarationSyntax or DelegateDeclarationSyntax)
                {
                    CheckType(member, model);
                }
                else if(FindAttribute(member.AttributeLists) is { } attribute)
                {
                    CheckAttributeForm(attribute, $"member '{MemberName(member)}' of '{symbol.Name}'", problems);
                }
                else
                {
                    problems.Add($"{File(member)}: member '{MemberName(member)}' of '{symbol.Name}' has no [GeneratedCode]");
                }
            }
        }
    }

    private static void CheckAttributeForm(AttributeSyntax attribute, string what, List<string> problems)
    {
        if(attribute.Name.ToString() != GeneratedCodeName)
        {
            problems.Add($"{File(attribute)}: {what} uses '{attribute.Name}', expected '{GeneratedCodeName}'");
        }

        if(attribute.Parent is AttributeListSyntax { Target: { } target })
        {
            problems.Add($"{File(attribute)}: {what} has [GeneratedCode] with the target '{target.Identifier.Text}:'");
        }

        if(attribute.ArgumentList is not { Arguments: [{ } tool, { } version] }
            || tool.ToString() != "\"SourceGen.Ioc\""
            || !VersionRegex.IsMatch(version.ToString()))
        {
            problems.Add($"{File(attribute)}: {what} has [GeneratedCode] with wrong arguments: {attribute}");
        }
    }

    private static AttributeSyntax? FindAttribute(SyntaxList<AttributeListSyntax> lists) => lists
        .SelectMany(static l => l.Attributes)
        .FirstOrDefault(static a => a.Name.ToString() is var name
            && (name.EndsWith("GeneratedCode", StringComparison.Ordinal) || name.EndsWith("GeneratedCodeAttribute", StringComparison.Ordinal)));

    private static string MemberName(MemberDeclarationSyntax member) => member switch
    {
        MethodDeclarationSyntax m => m.Identifier.Text,
        PropertyDeclarationSyntax p => p.Identifier.Text,
        FieldDeclarationSyntax f => string.Join(", ", f.Declaration.Variables.Select(static v => v.Identifier.Text)),
        ConstructorDeclarationSyntax c => $"{c.Identifier.Text}()",
        EventDeclarationSyntax e => e.Identifier.Text,
        EventFieldDeclarationSyntax e => string.Join(", ", e.Declaration.Variables.Select(static v => v.Identifier.Text)),
        _ => member.Kind().ToString(),
    };

    private static string File(SyntaxNode node) => Path.GetFileName(node.SyntaxTree.FilePath);

    private static string Line(SyntaxNode node) => $"line {node.GetLocation().GetLineSpan().StartLinePosition.Line + 1}";

    [GeneratedRegex("""^"\d+\.\d+\.\d+"$""")]
    private static partial Regex VersionRegex { get; }
}
